(()=>{
 const films=[...document.querySelectorAll('video[data-film]')],mobile=matchMedia('(max-width:767px)'),reduce=matchMedia('(prefers-reduced-motion:reduce)'),visible=new Set();
 function buttons(v){const b=v.closest('.helpu-film'),name=b.dataset.name;b.querySelector('.film-play').textContent=v.paused?'Reproduzir':'Pausar';b.querySelector('.film-play').setAttribute('aria-label',(v.paused?'Reproduzir ':'Pausar ')+name);b.querySelector('.film-sound').textContent=v.muted?'Som desligado':'Som ligado';b.querySelector('.film-sound').setAttribute('aria-pressed',String(!v.muted));b.querySelector('.film-sound').setAttribute('aria-label',(v.muted?'Ativar som de ':'Desativar som de ')+name);}
 function play(v){v.play().catch(()=>buttons(v));}
 function sources(){films.forEach(v=>{const variant=mobile.matches?'-mobile':'',src=`/apresentacao-publica/filmes/videos/${v.dataset.film}${variant}.mp4`;if(v.getAttribute('src')===src)return;const time=v.currentTime||0;v.muted=true;v.poster=`/apresentacao-publica/filmes/capas/${v.dataset.film}${variant}.jpg`;v.src=src;v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(time,Math.max(0,v.duration-.1));if(visible.has(v)&&!reduce.matches&&!v.dataset.manualPause&&!document.hidden)play(v);},{once:true});v.load();});}
 films.forEach(v=>{v.muted=true;const b=v.closest('.helpu-film');b.querySelector('.film-play').addEventListener('click',()=>{if(v.paused){delete v.dataset.manualPause;play(v);}else{v.dataset.manualPause='1';v.pause();}});b.querySelector('.film-sound').addEventListener('click',()=>{const enable=v.muted;films.forEach(other=>{if(other!==v)other.muted=true;});v.muted=!enable;if(enable){delete v.dataset.manualPause;play(v);}buttons(v);});['play','pause','volumechange'].forEach(e=>v.addEventListener(e,()=>buttons(v)));v.addEventListener('error',()=>{b.querySelector('.film-error').hidden=false;});v.addEventListener('loadeddata',()=>{b.querySelector('.film-error').hidden=true;});});
 const observer=new IntersectionObserver(entries=>{for(const {target:v,intersectionRatio} of entries){if(intersectionRatio>=.55){visible.add(v);if(!reduce.matches&&!v.dataset.manualPause&&!document.hidden)play(v);}else{visible.delete(v);v.pause();v.muted=true;}}},{threshold:[0,.55,1]});
 sources();films.forEach(v=>observer.observe(v));mobile.addEventListener('change',sources);document.addEventListener('visibilitychange',()=>{if(document.hidden)films.forEach(v=>{v.pause();v.muted=true;});else if(!reduce.matches)visible.forEach(v=>{if(!v.dataset.manualPause)play(v);});});reduce.addEventListener('change',()=>{if(reduce.matches)films.forEach(v=>{v.pause();v.muted=true;});});
})();
